function longestStrChain(words) {
  // a is a predecessor of b when b is one letter longer and a is a subsequence of b.
  const isPredecessor = (a, b) => {
    if (b.length !== a.length + 1) return false;
    let k = 0;
    for (const c of b) if (k < a.length && a[k] === c) k++;
    return k === a.length;
  };
  const list = words.slice().sort((x, y) => x.length - y.length);
  const longest = list.map(() => 1);
  for (let i = 0; i < list.length; i++) {
    for (let j = 0; j < i; j++) {
      if (isPredecessor(list[j], list[i])) longest[i] = Math.max(longest[i], longest[j] + 1);
    }
  }
  return Math.max(...longest);
}

