function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = large ? letters.slice(0, 3 + pick(24)) : (rand() < 0.5 ? 'ab' : 'abc');
  const maxLen = large ? 16 : 4;
  const n = large ? 1000 : 1 + pick(8);
  const words = [];
  while (words.length < n) {
    if (rand() < 0.6) {
      // Grow a chain one inserted letter at a time, skipping some of its words.
      let word = alphabet[pick(alphabet.length)];
      const target = 1 + pick(maxLen);
      while (word.length < target && words.length < n) {
        if (rand() < 0.85) words.push(word);
        const at = pick(word.length + 1);
        word = word.slice(0, at) + alphabet[pick(alphabet.length)] + word.slice(at);
      }
      if (words.length < n) words.push(word);
    } else {
      const length = 1 + pick(maxLen);
      let word = '';
      for (let i = 0; i < length; i++) word += alphabet[pick(alphabet.length)];
      words.push(word);
    }
  }
  for (let i = words.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [words[i], words[j]] = [words[j], words[i]];
  }
  return [words];
}
